import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"ADR-084 — Decompose the data.ts mega-client into $lib/data/ submodules","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-084.md","filePath":"adr/ADR-084.md"}'),d={name:"adr/ADR-084.md"};function r(c,e,i,n,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-084-—-decompose-the-data-ts-mega-client-into-lib-data-submodules" tabindex="-1">ADR-084 — Decompose the <code>data.ts</code> mega-client into <code>$lib/data/</code> submodules <a class="header-anchor" href="#adr-084-—-decompose-the-data-ts-mega-client-into-lib-data-submodules" aria-label="Permalink to &quot;ADR-084 — Decompose the `data.ts` mega-client into `$lib/data/` submodules&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-08-05 Gates · architectural-review R6 (data.ts accreting business logic vs. TA.md §constraints &quot;no hidden business logic in the data client&quot;) Builds on · ADR-006 (data client), ADR-017 (locale-overlay merge)</p></blockquote><p><strong>Gating sentence</strong>: the 2,554-line <code>src/lib/data.ts</code> mega-client is decomposed <strong>incrementally</strong> into <code>$lib/data/</code> submodules over a shared <code>$lib/data/core.ts</code> fetch+cache+i18n-overlay keystone; <strong><code>data.ts</code> stays as a re-export barrel</strong> so all 65 consumers (<code>from &#39;$lib/data&#39;</code>) keep working with ZERO import changes. <strong>Phase 1 (this ADR)</strong> extracts the keystone (<code>core.ts</code>) and the flagged business logic — the hero-override gallery builders (<code>galleries.ts</code>). Phases 2+ peel domain loaders (universe, science, stations, provenance) as separate, independently-shippable passes.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>data.ts</code> is 2,554 lines / 147 exports — the single data client every route imports. The architectural review (R6, MED) flagged it as eroding the TA.md §constraints rule &quot;no hidden business logic in the data client&quot;: it mixes pure fetch+cache+overlay loaders with <strong>business logic</strong> — the gallery-URL builders that orchestrate hero-override reordering (<code>getMissionGallery</code>/<code>getFleetGallery</code>/<code>getCategoryGallery</code> + 11 more, each doing <code>loadHeroOverrides</code> + <code>applyHeroOverride</code> + URL synthesis). It has also become an implicit god-module: a change anywhere risks the whole client.</p><p>Two facts make a safe split tractable (verified in code):</p><ol><li><strong>Consumers import barrel-style</strong> — 65 files do <code>from &#39;$lib/data&#39;</code>, none reach into internal symbols. A re-export barrel is transparent to them.</li><li><strong>The gallery builders depend only on <code>get()</code> + <code>assetOrigin</code> + <code>$lib/image-hero</code></strong> (and each other) — NOT on the domain loaders. So they extract without a circular dependency.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><p><strong>A shared keystone, not a barrel of copies.</strong> <code>$lib/data/core.ts</code> owns the fetch+cache+i18n-overlay primitives — <code>get&lt;T&gt;()</code>, the <code>cache</code> + <code>i18nBundles</code> maps, <code>loadI18nBundle</code>, the <code>FetchLike</code> type, and <code>resetCoreCache()</code>. Every current and future submodule imports <code>get</code> from here. This is the single source of the caching contract (ADR-006/017); it must not be duplicated.</p></li><li><p><strong>Extract the flagged business logic first.</strong> <code>$lib/data/galleries.ts</code> owns the hero-override gallery builders + their helpers (<code>GALLERY_ID_ALIASES</code>, <code>gallerySiteIdVariants</code>, the internal <code>getCategoryGallery</code>). This is the concrete R6 fix — the &quot;business logic in the client&quot; moves out, importing <code>get</code> from <code>core</code> and <code>loadHeroOverrides</code>/<code>applyHeroOverride</code> from <code>$lib/image-hero</code>.</p></li><li><p><strong><code>data.ts</code> becomes a thin re-export barrel + the remaining domain loaders.</strong> It imports <code>get</code>/<code>FetchLike</code> from <code>core</code>, re-exports everything from <code>galleries</code>, and keeps <code>__resetCache</code> (which calls <code>resetCoreCache()</code> then clears its own provenance vars). Consumers see no change.</p></li><li><p><strong>Phases 2+ are separate PRs, one domain at a time.</strong> Universe (<code>getNamedStars</code>, <code>getExoplanetSystems</code>, <code>getDeepSkyObjects</code>, <code>getMilkyWaySchematic</code>, <code>getLocalGroup</code>, <code>getBlackHoles</code>, <code>getCultureDoors</code>), science (<code>getScienceSection</code>/<code>getScienceTab</code>/<code>getProgram</code>/<code>getEssay</code>), stations (ISS/Tiangong), and provenance (image/audio/logos/text/badges) each peel into <code>$lib/data/&lt;domain&gt;.ts</code> importing <code>core</code>, re-exported by <code>data.ts</code>. Each phase is independently green-testable and low-risk because the barrel keeps imports stable. The full end-state is <code>data.ts</code> = a barrel; the loaders live in domain files.</p></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive</strong>: the caching contract has one home; the constraint-violating gallery logic is out of the client; the god-module shrinks per phase without a big-bang rewrite; each phase is a small, reviewable diff with zero consumer churn.</li><li><strong>Cost</strong>: a re-export barrel adds one indirection hop (negligible; tree-shaking handles it). During Phase 1 the barrel and submodules must agree on the <code>get()</code> signature — enforced by the type system + the existing <code>data.test.ts</code> suite.</li><li><strong>Risk</strong>: circular imports if a submodule imported <code>data.ts</code> — avoided by the rule &quot;submodules import <code>core</code>, never <code>data.ts</code>; <code>data.ts</code> imports submodules.&quot; Galleries reference each other within <code>galleries.ts</code> (fine).</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Big-bang full decomposition</strong> — split all ~10 domains at once. Rejected: a 2.5k-line file touched by 65 consumers in one PR is high-risk and unreviewable; the phased barrel gives the same end-state safely.</li><li><strong>Leave it, just extract galleries</strong> — addresses R6 literally but leaves the keystone entangled, so Phase 2 would have to extract <code>core</code> anyway. Doing <code>core</code> in Phase 1 unblocks all later phases for the same cost.</li><li><strong>A <code>$lib/data/index.ts</code> barrel replacing <code>data.ts</code></strong> — would require rewriting 65 import paths (<code>$lib/data</code> already resolves to <code>data.ts</code>; making it a dir needs an index). Keeping <code>data.ts</code> as the barrel is zero-churn.</li></ul>',13)])])}const m=o(d,[["render",r]]);export{u as __pageData,m as default};
